'use strict';

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var SharedArrayBuffer = require( '@stdlib/array/shared-buffer' );
var getGlobal = require( '@stdlib/utils/global' );
var main = require( './../lib/main.js' );
var publicMain = require( './../lib' );

/**
* Supplies a valid independent lower 2x2 panel.
* @param {*} fn - argument
* @param {*} a - argument
* @param {*} k - argument
* @param {*} p - argument
* @param {*} w - argument
* @returns {integer} INFO
*/
function valid(fn, a, k, p, w) {
	return fn.ndarray('lower', 2, 2, k, 0, a, 1, 2, 0, p, 1, 0, w, 1, 2, 0);
}
/**
* Ensures a rejected call has not changed any active storage.
* @param {*} t - argument
* @param {*} fn - argument
*/
function unchanged(t, fn) {
	var a;
	var k;
	var p;
	var w;
	a = new Float64Array([
		0,
		4,
		4,
		0
	]);
	k = new Int32Array([91]);
	p = new Int32Array([
		12,
		13
	]);
	w = new Float64Array([
		21,
		22,
		23,
		24
	]);
	t.throws(function call() { // eslint-disable-line no-loop-func
		fn(a, k, p, w);
	});
	t.deepEqual(a, new Float64Array([
		0,
		4,
		4,
		0
	]), 'no factor writes');
	t.deepEqual(k, new Int32Array([91]), 'no count write');
	t.deepEqual(p, new Int32Array([
		12,
		13
	]), 'no pivot writes');
	t.deepEqual(w, new Float64Array([
		21,
		22,
		23,
		24
	]), 'no scratch writes');
}
tape('empty order initializes only the active count slot after scalar checks', function test(t) {
	var trap;
	var k;
	var f;
	var i;
	k = new Int32Array([
		9,
		8,
		7
	]);
	trap = {};
	Object.defineProperty(trap, 'length', {
		'get': function get() {
			throw new Error('inactive length accessed');
		}
	});
	for (i = 0; (i < 2); i++) {
		k = new Int32Array([
			9,
			8,
			7
		]);
		f = ( (i === 0) ) ? main : publicMain;
		t.strictEqual(f.ndarray('lower', 0, 2147483647, k, 1, trap, NaN, Infinity, undefined, trap, NaN, NaN, trap, NaN, NaN, NaN), 0, 'new safe-empty status');
		t.deepEqual(k, new Int32Array([
			9,
			0,
			7
		]), 'only KB slot changed');
		t.strictEqual(f(102, 121, 0, 2, k, trap, 1, trap, trap, 1), 0, 'numeric selectors accepted');
		t.throws(function call() { // eslint-disable-line no-loop-func
			f('column-major', 'upper', 0, 1, k, trap, 1, trap, trap, 1);
		}, RangeError, 'NB validated before KB write');
		t.throws(function call() { // eslint-disable-line no-loop-func
			f.ndarray('lower', 2147483648, 2, undefined, 0, undefined, 1, 2, 0, undefined, 1, 0, undefined, 1, 2, 0);
		}, RangeError, 'N cap before buffers');
		t.throws(function call() { // eslint-disable-line no-loop-func
			f('column-major', 'upper', 0, 2, undefined, trap, 0, trap, trap, 1);
		}, RangeError, 'main LDA before buffer access');
	}
	t.end();
});
tape('invalid dtype, geometry and alias calls reject before all writes', function test(t) {
	unchanged(t, function call(a, k, p, w) {
		return main.ndarray('lower', 2, 2, k, 0, a, 1, 1, 0, p, 1, 0, w, 1, 2, 0);
	});
	unchanged(t, function call(a, k, p, w) {
		return main.ndarray('lower', 2, 2, k, 0, a, 1, 2, 0, p, 0, 0, w, 1, 2, 0);
	});
	unchanged(t, function call(a, k, p, w) {
		return main.ndarray('lower', 2, 2, k, 0, a, 1, 2, -1, p, 1, 0, w, 1, 2, 0);
	});
	unchanged(t, function call(a, k, p) {
		return valid(main, a, k, p, a);
	});
	unchanged(t, function call(a, k, p, w) {
		return main.ndarray('lower', 2, 2, k, 0, a, 1, 2, 0, new Float64Array(2), 1, 0, w, 1, 2, 0);
	});
	unchanged(t, function call(a, k, p, w) {
		return main.ndarray('lower', 2, 2, k, 0, a, 1, 2, 0, p, 1, 0, w, 0, 2, 0);
	});
	t.end();
});
tape('ordinary signed equal-negative pivots and singular INFO are produced', function test(t) {
	var a;
	var k;
	var p;
	var w;
	a = new Float64Array([
		0,
		4,
		4,
		0
	]);
	k = new Int32Array(1);
	p = new Int32Array([
		123,
		456
	]);
	w = new Float64Array(4);
	t.strictEqual(valid(main, a, k, p, w), 0);
	t.strictEqual(k[0], 2);
	t.deepEqual(p, new Int32Array([
		-2,
		-2
	]), 'ordinary equal negative pair, not rook');
	a = new Float64Array([0]);
	p = new Int32Array([123]);
	w = new Float64Array(2);
	t.strictEqual(main('column-major', 'upper', 1, 2, k, a, 1, p, w, 1), 1, 'positive one-based singular position returned');
	t.strictEqual(k[0], 1, 'singular panel still completed');
	t.deepEqual(p, new Int32Array([1]));
	t.end();
});
tape('captured intrinsic view metadata ignores untrusted own accessors', function test(t) {
	var reads;
	var names;
	var a;
	var k;
	var p;
	var w;
	var i;
	a = new Float64Array([
		0,
		4,
		4,
		0
	]);
	k = new Int32Array(1);
	p = new Int32Array(2);
	w = new Float64Array(4);
	reads = 0;
	names = [
		'length',
		'buffer',
		'byteOffset',
		'byteLength'
	];
	for (i = 0; (i < names.length); i++) {
		Object.defineProperty(a, names[i], {
			'get': function get() { // eslint-disable-line no-loop-func
				reads += 1;
				throw new Error('untrusted metadata');
			}
		});
	}
	t.strictEqual(valid(publicMain, a, k, p, w), 0);
	t.strictEqual(reads, 0);
	t.deepEqual(p, new Int32Array([
		-2,
		-2
	]));
	t.end();
});
tape('SharedArrayBuffer storage is rejected without mutation', {
	'skip': (SharedArrayBuffer === null)
}, function test(t) {
	var clone;
	var b;
	var a;
	var k;
	var p;
	var w;
	b = new SharedArrayBuffer(128);
	clone = getGlobal().structuredClone;
	b = ( clone ) ? clone(b) : b;
	a = new Float64Array(b, 0, 4);
	k = new Int32Array(1);
	p = new Int32Array(2);
	w = new Float64Array(4);
	a.set([
		0,
		4,
		4,
		0
	]);
	t.throws(function call() { // eslint-disable-line no-loop-func
		valid(publicMain, a, k, p, w);
	}, TypeError);
	t.deepEqual(a, new Float64Array([
		0,
		4,
		4,
		0
	]));
	t.deepEqual(k, new Int32Array([0]));
	t.end();
});
